Below is a **Python FastAPI** implementation for the local sidecar engine (with background worker thread, thread-safe queue, health endpoint, and graceful shutdown), followed by **Rust/Tauri** and **Node.js** clients that spawn the process and poll `/api/health` with exponential backoff.

---

## **1. Python FastAPI Sidecar Engine (`main.py`)**
```python
import asyncio
import signal
import sys
import threading
import time
from queue import Queue
from typing import Optional

from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
import psutil  # For hardware monitoring (install: `pip install psutil`)

app = FastAPI()

# Thread-safe queue for background tasks
task_queue = Queue()
shutdown_event = threading.Event()  # Signal for graceful shutdown

def worker():
    """Background worker thread processing tasks from the queue."""
    while not shutdown_event.is_set():
        try:
            task = task_queue.get(timeout=1)  # Wait with timeout to allow shutdown checks
            if task is None:  # Sentinel value to break loop on shutdown
                continue
            print(f"[Worker] Processing task: {task}")
            time.sleep(0.5)  # Simulate work
        except queue.Empty:
            pass

def start_worker():
    """Start the background worker thread."""
    worker_thread = threading.Thread(target=worker, daemon=True)
    worker_thread.start()
    print("[Sidecar] Worker thread started.")

@app.on_event("startup")
async def startup_event():
    """Initialize the sidecar on startup."""
    start_worker()

@app.post("/api/tasks")
async def add_task(task: str):
    """Add a task to the queue (for demonstration)."""
    if shutdown_event.is_set():
        raise HTTPException(status_code=503, detail="Service shutting down")
    task_queue.put(task)
    return {"status": "Task queued"}

@app.get("/api/health", response_model=dict)
async def health_check() -> dict:
    """Report hardware state (RAM/VRAM usage)."""
    if shutdown_event.is_set():
        raise HTTPException(status_code=503, detail="Service shutting down")

    # Simulate VRAM usage (replace with actual GPU monitoring if needed)
    vram_usage = psutil.virtual_memory().percent
    ram_usage = psutil.cpu_percent(interval=None)  # CPU% as proxy for RAM load

    return {
        "status": "healthy",
        "timestamp": time.time(),
        "ram_usage_percent": ram_usage,
        "vram_usage_percent": vram_usage,
    }

def graceful_shutdown(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"[Sidecar] Received signal {signum}, initiating shutdown...")
    shutdown_event.set()
    task_queue.put(None)  # Sentinel to wake up worker thread
    sys.exit(0)

if __name__ == "__main__":
    # Register signal handlers
    signal.signal(signal.SIGINT, graceful_shutdown)
    signal.signal(signal.SIGTERM, graceful_shutdown)

    import uvicorn
    uvicorn.run(
        app,
        host="127.0.0.1",
        port=8000,
        log_level="info",
    )
```

