## **2. Rust/Tauri Client (`src-tauri/src/main.rs`)**
```rust
use std::process::{Command, Stdio};
use std::thread;
use std::time::{Duration, Instant};
use serde_json::Value;
use reqwest::Error;

#[tauri::command]
async fn start_sidecar() -> Result<(), String> {
    // Spawn the Python FastAPI process
    let mut child = Command::new("python3")
        .arg("./main.py")  // Path to your Python script
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|e| format!("Failed to start sidecar: {}", e))?;

    Ok(())
}

#[tauri::command]
async fn poll_health(max_retries: u32) -> Result<Value, String> {
    let mut backoff = Duration::from_secs(1);
    let mut retries = 0;
    let start_time = Instant::now();

    loop {
        match reqwest::get("http://localhost:8000/api/health")
            .await
            .map_err(|e| format!("Request failed: {}", e))?
            .json::<Value>()
            .await
        {
            Ok(health) => return Ok(health),
            Err(e) if retries < max_retries => {
                thread::sleep(backoff);
                backoff *= 2;  // Exponential backoff
                retries += 1;
                println!("Retry {}: {}", retries, e);
            }
            _ => break,
        }

        if start_time.elapsed().as_secs() > 30 {  // Timeout after 30s
            return Err("Polling timed out".to_string());
        }
    }

    Err("Sidecar failed to respond".to_string())
}

fn main() {
    tauri::Builder::default()
        .invoke_handler(tauri::generate_handler![start_sidecar, poll_health])
        .run(tauri::generate_context!())
        .expect("Error while running Tauri application");
}
```

