## **3. Node.js Client (`client.js`)**
```javascript
const { spawn } = require('child_process');
const axios = require('axios');
const { setTimeout: delay } = require('timers/promises');

async function startSidecar() {
    return new Promise((resolve, reject) => {
        const child = spawn('python3', ['./main.py'], {
            stdio: ['ignore', 'ignore', 'inherit'],
        });

        child.on('error', (err) => reject(err));
        child.on('exit', (code) => {
            if (code !== 0) reject(new Error(`Sidecar exited with code ${code}`));
            else resolve(child);
        });
    });
}

async function pollHealth(maxRetries = 10) {
    let retries = 0;
    const backoff = Math.pow(2, retries); // Exponential backoff

    while (retries < maxRetries) {
        try {
            const response = await axios.get('http://localhost:8000/api/health');
            return response.data;
        } catch (err) {
            if (retries >= maxRetries - 1) throw err; // Final attempt failed
            retries++;
            console.log(`Retry ${retries}: ${err.message}`);
            await delay(backoff * 1000); // Wait backoff seconds
        }
    }
}

async function main() {
    try {
        const child = await startSidecar();
        console.log('Sidecar started successfully');

        const health = await pollHealth();
        console.log('Health status:', health);
    } catch (err) {
        console.error('Error:', err.message);
        process.exit(1);
    }
}

main();
```

